package dev.slithergoh.pixelmonradar.client.screen;

import dev.slithergoh.pixelmonradar.client.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import java.util.*;
public final class RadarScreen extends Screen{private EditBox search;private List<PokemonInfo>visible=List.of();private int scroll;public RadarScreen(){super(Component.literal("Pixelmon Radar"));}@Override protected void init(){int l=width/2-240;search=new EditBox(font,l+12,45,230,22,Component.literal("Search Pokemon"));search.setHint(Component.literal("Search Pokemon..."));search.setValue(RadarSettings.search);search.setResponder(s->RadarSettings.search=s.trim());addRenderableWidget(search);addRenderableWidget(Button.builder(Component.literal("Sort: "+RadarSettings.sortMode),b->{RadarSettings.SortMode[]m=RadarSettings.SortMode.values();RadarSettings.sortMode=m[(RadarSettings.sortMode.ordinal()+1)%m.length];b.setMessage(Component.literal("Sort: "+RadarSettings.sortMode));}).bounds(l+248,45,110,22).build());addRenderableWidget(Button.builder(Component.literal("Range "+RadarSettings.pokemonRange+"m"),b->{RadarSettings.pokemonRange=RadarSettings.pokemonRange>=256?32:RadarSettings.pokemonRange+32;b.setMessage(Component.literal("Range "+RadarSettings.pokemonRange+"m"));}).bounds(l+364,45,104,22).build());addRenderableWidget(toggle(l+12,72,105,"Shiny only",()->RadarSettings.shinyOnly,v->RadarSettings.shinyOnly=v));addRenderableWidget(toggle(l+122,72,105,"Rare only",()->RadarSettings.rareOnly,v->RadarSettings.rareOnly=v));addRenderableWidget(toggle(l+232,72,105,"HUD",()->RadarSettings.hudEnabled,v->RadarSettings.hudEnabled=v));addRenderableWidget(toggle(l+342,72,126,"Alerts",()->RadarSettings.alertsEnabled,v->RadarSettings.alertsEnabled=v));}private interface Get{boolean get();}private interface Set{void set(boolean v);}private Button toggle(int x,int y,int w,String n,Get g,Set s){return Button.builder(Component.literal(n+": "+(g.get()?"ON":"OFF")),b->{s.set(!g.get());b.setMessage(Component.literal(n+": "+(g.get()?"ON":"OFF")));RadarSettings.save();}).bounds(x,y,w,20).build();}private void refresh(){ArrayList<PokemonInfo>l=new ArrayList<>(PokemonScanner.scan());String q=RadarSettings.search.toLowerCase();if(!q.isBlank())l.removeIf(p->!p.name().toLowerCase().contains(q));Comparator<PokemonInfo>c=switch(RadarSettings.sortMode){case LEVEL->Comparator.comparingInt(PokemonInfo::level).reversed();case NAME->Comparator.comparing(PokemonInfo::name,String.CASE_INSENSITIVE_ORDER);case RARITY->Comparator.comparing(PokemonInfo::rare).reversed().thenComparingDouble(PokemonInfo::distance);default->Comparator.comparingDouble(PokemonInfo::distance);};l.sort(c);visible=l;}@Override public void renderBackground(GuiGraphics g,int mx,int my,float pt){}@Override public void render(GuiGraphics g,int mx,int my,float pt){refresh();int l=width/2-240,r=l+480;g.fill(l,18,r,height-18,0xE00D1720);g.fill(l,18,r,38,0xFF173A52);g.drawString(font,"PIXELMON RADAR",l+12,25,0xFFFFFF,true);g.drawString(font,visible.size()+" nearby",r-65,25,0xA9E8FF,false);super.render(g,mx,my,pt);int max=Math.max(1,(height-142)/48);scroll=Math.min(scroll,Math.max(0,visible.size()-max));int y=106;for(int i=scroll;i<visible.size()&&i<scroll+max;i++){PokemonInfo p=visible.get(i);boolean tr=p.entityId()==RadarSettings.trackedEntityId;g.fill(l+10,y-3,r-10,y+40,tr?0xFF285747:0xCC17232D);if(p.sprite()!=null)g.blit(p.sprite(),l+16,y,0,0,36,36,36,36);int col=p.shiny()?0x6FFFFF:p.rare()?0xFFD45F:0xFFFFFF;g.drawString(font,p.name()+"   Lv."+p.level(),l+58,y+2,col,true);g.drawString(font,Math.round(p.distance())+"m   XYZ "+p.pos().getX()+" "+p.pos().getY()+" "+p.pos().getZ(),l+58,y+14,0xC2D0D8,false);String meta=p.gender()+"  •  "+p.form()+(p.boss()?"  •  Boss "+p.bossTier():"")+p.badges();g.drawString(font,meta,l+58,y+26,p.rare()?0xFFD45F:0x8FA4B1,false);g.drawString(font,tr?"TRACKING":"TRACK",r-62,y+14,tr?0x75FFB0:0x8FA4B1,false);y+=48;}g.drawString(font,"Click a Pokemon card to track  •  wheel to scroll",l+12,height-31,0x91A5B3,false);}@Override public boolean mouseClicked(double mx,double my,int b){int l=width/2-240,max=Math.max(1,(height-142)/48),y=106;if(mx>=l+10&&mx<=l+470)for(int i=scroll;i<visible.size()&&i<scroll+max;i++,y+=48)if(my>=y-3&&my<=y+40){int id=visible.get(i).entityId();RadarSettings.trackedEntityId=RadarSettings.trackedEntityId==id?-1:id;return true;}return super.mouseClicked(mx,my,b);}@Override public boolean mouseScrolled(double mx,double my,double sx,double sy){int max=Math.max(1,(height-142)/48);scroll=Math.max(0,Math.min(Math.max(0,visible.size()-max),scroll+(sy<0?1:-1)));return true;}@Override public void onClose(){RadarSettings.save();super.onClose();}@Override public boolean isPauseScreen(){return false;}}
